//
// What the mock received of each kind of credential the client sends, and a call that needs none.

import assert from 'node:assert/strict'
import { after, before, test } from 'node:test'
import { GitHub } from "github-like-sdk"
import { mock } from '../mock/server.mjs'

let server
let client

before(async () => {
  server = await mock()
  client = new GitHub({ baseURL: server.url, token: 'test-credential', appKey: 'test-credential', admin: { username: 'user', password: 'pass' }, maxRetries: 0 })
})

after(() => server.close())

/** The request the mock answered last; `null` against a server of your own. */
const last = () => server.requests?.at(-1) ?? null

test("Token: sent by users.me", async () => {
  await client.users.me()
  const r = last()
  if (r === null) return
  assert.equal(r.headers.authorization, 'Bearer test-credential')
})

test("AppKey: sent by apps.hook", async () => {
  await client.apps.hook()
  const r = last()
  if (r === null) return
  assert.equal(r.headers["x-app-key"], 'test-credential')
})

test("Admin: sent by enterprise.settings", async () => {
  await client.enterprise.settings()
  const r = last()
  if (r === null) return
  assert.equal(r.headers.authorization, `Basic ${Buffer.from('user:pass').toString('base64')}`)
})

test("no credential: meta.get needs none", async () => {
  const none = new GitHub({ baseURL: server.url, maxRetries: 0, token: null, appKey: null, admin: null })
  await none.meta.get()
  const r = last()
  if (r === null) return
  assert.equal(r.headers.authorization, undefined)
  assert.equal(r.headers["x-app-key"], undefined)
})
